async function flushNow() {
    if (buffer.length === 0) return { sent: 0 };

    const metrics = buffer.splice(0, cappedMaxBatch);
    const headers = { 'Content-Type': 'application/json', Accept: 'application/json' };
    const correlationId = readCorrelationId();
    if (correlationId) headers['X-Correlation-ID'] = correlationId;

    try {
        const response = await resolvedFetcher(endpoint, { method: 'POST', headers, body: JSON.stringify({ metrics }) });
        if (!response || !response.ok) {
            buffer.unshift(...metrics);
            if (!warned) { warned = true; console.warn('MetricsBatcher failed to flush metrics', { status: response?.status }); }
            return { sent: 0 };
        }
        return { sent: metrics.length };
    } catch (error) {
        buffer.unshift(...metrics);
        if (!warned) { warned = true; console.warn('MetricsBatcher failed to flush metrics', error); }
        return { sent: 0 };
    }
}
